script:
class Component extends DCLogic {
shared(k, d) { try { var S = parent.SONNA_STORE; return S ? S.get(k, d) : d; } catch (e) { return d; } }
saveShared(k, v) { let r = false; try { r = parent.SONNA_STORE ? parent.SONNA_STORE.set(k, v) : false; } catch (e) {} if (!r) this._fail = true; return r; }
compress(files, done) {
const list = Array.from(files).filter((f) => /^image\//.test(f.type));
if (!list.length) { this.setState({ msg: 'Không tìm thấy tệp ảnh hợp lệ.' }); return; }
const out = []; let left = list.length, failed = 0;
const finish = (url, error) => {
if (url) out.push(url);
if (error) failed++;
if (--left !== 0) return;
if (out.length) done(out, failed);
else this.setState({ msg: 'Chọn JPG, PNG, GIF hoặc WEBP, tối đa 8MB mỗi ảnh.' });
};
list.forEach((f) => {
if (f.size > 8 * 1024 * 1024) return finish('', new Error('Ảnh vượt quá giới hạn 8MB.'));
const rd = new FileReader();
rd.onerror = () => finish('', new Error('Could not read image file.'));
rd.onload = () => {
if (f.type.toLowerCase() === 'image/gif' || f.type.toLowerCase() === 'image/webp') {
const dataUrl = typeof rd.result === 'string' ? rd.result : '';
if (!dataUrl) return finish('', new Error('Không đọc được ảnh.'));
const api = parent.SONNA_API;
if (!api) return finish('', new Error('Thiếu kết nối máy chủ.'));
api('POST', '/api/admin/upload', { dataUrl }).then((r) => finish(r && r.url ? r.url : '', r && r.url ? null : new Error((r && r.error) || 'Lỗi máy chủ.'))).catch(() => finish('', new Error('Lỗi kết nối máy chủ.')));
return;
}
const im = new Image();
im.onerror = () => finish('', new Error('Ảnh không giải mã được.'));
im.onload = () => {
try {
const k = Math.min(1, 1000 / Math.max(im.width, im.height));
const cv = document.createElement('canvas'); cv.width = Math.round(im.width * k); cv.height = Math.round(im.height * k);
const ctx = cv.getContext('2d');
if (!ctx) return finish('', new Error('Không xử lý được ảnh.'));
ctx.drawImage(im, 0, 0, cv.width, cv.height);
const dataUrl = cv.toDataURL('image/jpeg', 0.8), api = parent.SONNA_API;
if (!api) return finish('', new Error('Thiếu kết nối máy chủ.'));
api('POST', '/api/admin/upload', { dataUrl }).then((r) => finish(r && r.url ? r.url : '', r && r.url ? null : new Error((r && r.error) || 'Lỗi máy chủ.'))).catch(() => finish('', new Error('Lỗi kết nối máy chủ.')));
} catch (error) { finish('', error); }
};
im.src = rd.result;
};
rd.readAsDataURL(f);
});
}
setState(p) {
super.setState(p);
if (['listed', 'ov', 'edits', 'added', 'subPics', 'accPics', 'delSubs', 'rulesData'].some((k) => k in p)) {
const S = this.state; this._fail = false;
this.saveShared('acc', { listed: S.listed, ov: S.ov, edits: S.edits, added: S.added, subPics: S.subPics, accPics: S.accPics, delSubs: S.delSubs, rulesData: S.rulesData });
if (this._fail) super.setState({ msg: 'Không lưu được: bộ nhớ trình duyệt đầy. Hãy dùng ít ảnh hơn hoặc ảnh nhỏ hơn.' });
}
}
mount() {
this.refreshInventory();
document.addEventListener('keydown', (e) => {
if (e.key !== 'Escape') return;
if (this.state.cf) this.setState({ cf: null }); else if (this.state.edit) this.setState({ edit: null });
});
}
refreshInventory() {
const api = parent.SONNA_API;
if (!api) return this.setState({ inventoryMsg: 'Không kết nối được máy chủ.' });
const shared = parent.SONNA_STORE;
const pending = shared ? Promise.all([shared.flush('acc'), shared.flush('catalog')]) : Promise.resolve([]);
pending.then((writes) => { if (writes.some((x) => x && x._status !== 200)) throw new Error('Could not save inventory before refresh.'); return api('GET', '/api/store'); }).then((r) => {
if (r._status !== 200 || !r.data || !r.data.acc || !Array.isArray(r.data.acc.listed)) return this.setState({ inventoryMsg: r.error || 'Không tải được kho mới nhất.' });
const acc = r.data.acc, catalog = r.data.catalog || {};
if (shared) { shared.set('acc', acc); shared.set('catalog', catalog); }
this._lastCat = '';
this.setState({ listed: acc.listed, ov: acc.ov || {}, added: acc.added || [], edits: acc.edits || {}, subPics: acc.subPics || {}, accPics: acc.accPics || {}, delSubs: acc.delSubs || {}, rulesData: acc.rulesData || [], customCats: catalog.categories || [], inventoryMsg: 'Đã làm mới kho từ máy chủ.' });
}).catch((error) => { console.error('[SONNA] Không tải được kho acc mới nhất:', error); this.setState({ inventoryMsg: 'Không tải được kho mới nhất. Hãy thử lại.' }); });
}
flash(text, bad) {
this.setState({ toast: text, toastBad: !!bad });
clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 5000);
}
delAccs(ids) {
const ov = { ...this.state.ov }; const sel = { ...this.state.selIds };
ids.forEach((id) => { ov[id] = { ...(ov[id] || {}), del: true }; delete sel[id]; });
this.setState({ ov, selIds: sel, cf: null, edit: null });
this.flash('Đã xóa ' + ids.length + ' acc.');
}
delSubAndAccs(c) {
const ov = { ...this.state.ov };
c.ids.forEach((id) => { ov[id] = { ...(ov[id] || {}), del: true }; });
const p = { ov, delSubs: { ...this.state.delSubs, [c.sid]: true }, cf: null };
if (this.state.sub === c.sid) p.sub = 'all';
if (c.rulesKeep) p.rulesData = c.rulesKeep;
this.setState(p);
this.flash('Đã xóa mục con' + (c.ids.length ? ' và ' + c.ids.length + ' acc bên trong' : '') + '.');
}

state = {
cat: 'reroll-ios',
sub: 'all',
formCat: 'reroll-ios',
customCats: (this.shared('catalog', {}) || {}).categories || [],
customCatOpen: false, customCatName: '', customCatPlatform: 'Android',
mode: 'bulk',
bulk: '', accImgs: [],
edits: this.shared('acc', {}).edits || {},
added: this.shared('acc', {}).added || [],
subPics: this.shared('acc', {}).subPics || {},
accPics: this.shared('acc', {}).accPics || {},
delSubs: this.shared('acc', {}).delSubs || {},
rulesData: this.shared('acc', {}).rulesData || null,
giftSubSel: '',
edit: null, cf: null, toast: '', toastBad: false,
rBuy: '1', rGive: '1', rBuySel: '', rGiveSel: '', rFrom: '', rTo: '',
lv: '', cr: '', ch: '', tn: '',
q: '', listed: this.shared('acc', {}).listed || [], ov: this.shared('acc', {}).ov || {}, selIds: {}, inventoryFilter: 'unsold', msg: '', tk: '', mk: '', price: '', cost: '', subSel: ''
};
renderVals() {
const on = '#FF8A1F', off = '#A3ACC4', ok = '#43D9A0';
const st = this.state;
const num = (x) => parseInt(String(x).replace(/\D/g, ''), 10) || 0;
const fm = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '₫';
const nav = [
{ label: 'Tổng quan', href: 'AdminDashboard.dc.html' },
{ label: 'Quản lý acc', href: 'AdminAccounts.dc.html', active: true },
{ label: 'Đơn hàng', href: 'AdminOrders.dc.html' },
{ label: 'Thanh toán', href: 'AdminPayments.dc.html' },
{ label: 'Người dùng', href: 'AdminUsers.dc.html' },
{ label: 'Khuyến mãi', href: 'AdminPromos.dc.html' },
{ label: 'Nội dung website', href: 'AdminContent.dc.html' },
{ label: 'Báo cáo', href: '#bao-cao' },
{ label: 'Phân quyền', href: 'AdminRoles.dc.html' },
{ label: 'Nhật ký hoạt động', href: '#nhat-ky' }
].map((n) => ({ ...n, bg: n.active ? '#1F2538' : 'transparent', fg: n.active ? on : off }));

const cats = [
{ id: 'reroll-ios', label: 'Acc Reroll iOS', count: '0', col: '#52C7FF', plat: 'iOS', code: 'RI', hint: 'Mỗi acc thuộc một mục con (ví dụ 50.000-60.000 cc iOS). Liên kết mặc định Bandai Namco ID.' },
{ id: 'reroll-android', label: 'Acc Reroll Android', count: '0', col: '#43D9A0', plat: 'Android', code: 'RA', hint: 'Mỗi acc thuộc một mục con (ví dụ 50.000-60.000 cc Android). Liên kết mặc định Bandai Namco ID.' },
{ id: 'char-ios', label: 'Acc Character + Chrono iOS', count: '0', col: '#FFC24B', plat: 'iOS', code: 'CI', hint: 'Acc đã đầu tư trên iOS: cấp độ, Chrono, số nhân vật và danh sách nổi bật.' },
{ id: 'char-android', label: 'Acc Character + Chrono Android', count: '0', col: '#FF8A1F', plat: 'Android', code: 'CA', hint: 'Acc đã đầu tư trên Android: cấp độ, Chrono, số nhân vật và danh sách nổi bật.' },
{ id: 'team-meta', label: 'Team Meta', count: '0', col: '#FF6B7A', plat: '', code: 'TM', hint: 'Acc xây sẵn đội hình meta: nêu tên đội, nhân vật chính và chế độ phù hợp.' },
{ id: 'promo', label: 'Acc Khuyến Mãi', count: '0', col: '#C792FF', plat: '', code: 'KM', hint: 'Kho acc dùng để tặng theo chương trình khuyến mãi. Không bán lẻ, hệ thống tự lấy acc từ kho khi đơn đủ điều kiện.' }
];
const savedCatalog = this.shared('catalog', {}) || {};
(st.customCats || []).forEach((c) => { if (c && c.id && c.name) cats.push({ id: c.id, label: c.name, count: '0', col: c.color || '#5B1F7A', plat: c.platform || '', code: c.code || 'CUS', hint: 'Danh mục sản phẩm tùy chỉnh. Có thể bán acc lẻ hoặc tạo thư mục để gom acc.', custom: true }); });
const byId = {};
cats.forEach((c) => { byId[c.id] = c; });

const DEFAULT_SUBS = {
'reroll-ios': [
{ id: 'ria', title: '50.000-60.000 cc iOS', price: '350.000', stock: 18, promo: 'Mua 1 tặng 1' },
{ id: 'rib', title: '60.000-70.000 cc iOS', price: '420.000', stock: 12, promo: 'Chưa có' },
{ id: 'ric', title: '70.000-80.000 cc iOS', price: '500.000', stock: 8, promo: 'Chưa có' }
],
'reroll-android': [
{ id: 'raa', title: '50.000-60.000 cc Android', price: '330.000', stock: 24, promo: 'Chưa có' },
{ id: 'rab', title: '60.000-70.000 cc Android', price: '400.000', stock: 16, promo: 'Mua 2 tặng 1' },
{ id: 'rac', title: '70.000-80.000 cc Android', price: '480.000', stock: 12, promo: 'Chưa có' }
],
'promo': [
{ id: 'pa', title: '50.000-60.000 cc iOS', price: '', stock: 6, promo: '1 quy tắc' },
{ id: 'pb', title: '60.000-70.000 cc iOS', price: '', stock: 3, promo: 'Chưa dùng' },
{ id: 'pc', title: '50.000-60.000 cc Android', price: '', stock: 8, promo: '1 quy tắc' },
{ id: 'pd', title: '60.000-70.000 cc Android', price: '', stock: 5, promo: 'Chưa dùng' }
]
};
const SUBS = {};
Object.keys(DEFAULT_SUBS).forEach((catId) => {
const live = catId === 'promo'
? (Array.isArray(savedCatalog.giftSubs) ? savedCatalog.giftSubs : []).map((x) => ({ id: x.id, title: x.title, price: '' }))
: (Array.isArray(savedCatalog.subs) ? savedCatalog.subs : []).filter((x) => x.cat === catId).map((x) => ({ id: x.id, title: x.title, price: Number(x.price) > 0 ? String(Number(x.price)).replace(/\B(?=(\d{3})+(?!\d))/g, '.') : '' }));
SUBS[catId] = catId === 'promo' ? live : (live.length ? live : DEFAULT_SUBS[catId]);
});
(Array.isArray(savedCatalog.subs) ? savedCatalog.subs : []).forEach((x) => { if (!SUBS[x.cat]) SUBS[x.cat] = []; });

const val = (id, k, d) => (st.edits[id + ':' + k] !== undefined ? st.edits[id + ':' + k] : d);
const addCategory = () => {
const name = String(st.customCatName || '').trim();
if (name.length < 2 || name.length > 40) return this.setState({ msg: 'Tên danh mục cần từ 2 đến 40 ký tự.' });
const normalized = name.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
if (cats.some((c) => c.label.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase() === normalized)) return this.setState({ msg: 'Tên danh mục này đã tồn tại.' });
if ((st.customCats || []).length >= 20) return this.setState({ msg: 'Đã đạt giới hạn 20 danh mục tùy chỉnh.' });
const suffix = Date.now().toString(36);
const category = { id: 'product-' + suffix, name, code: 'P' + suffix.slice(-5).toUpperCase(), platform: st.customCatPlatform, color: '#5B1F7A' };
this.setState({ customCats: (st.customCats || []).concat(category), customCatName: '', customCatOpen: false, cat: category.id, formCat: category.id, sub: 'all', subSel: '', msg: 'Đã thêm danh mục ' + name + '.' });
};
const askDelCategory = (e, c) => {
if (e) e.stopPropagation();
if (!c.custom) return;
if (merged.some((r) => r.cat === c.id && !r.del) || getSubs(c.id).length) return this.flash('Danh mục còn acc hoặc thư mục. Hãy xóa hết acc và thư mục trước khi xóa danh mục.', true);
this.setState({ cf: { kind: 'category', id: c.id, name: c.label, title: 'Xóa danh mục?', text: 'Danh mục “' + c.label + '” sẽ bị xóa khỏi cửa hàng. Không thể hoàn tác.', btn: 'Xóa danh mục' } });
};
const setEdit = (id, k) => (e) => {
const v = e.target.value;
this.setState({ edits: { ...this.state.edits, [id + ':' + k]: v } });
};
const getSubs = (catId) => (SUBS[catId] || []).map((s) => { const matching = st.listed.map((a) => ({ ...a, ...(st.ov[a.id] || {}) })).filter((row) => row.cat === catId && row.sub === s.id && !row.del && String(row.tk || '').trim() && String(row.mk || '').trim()); return { ...s, stock: matching.filter((row) => catId === 'promo' ? row.status === 'Trong kho' : ['\u0110ang b\u00e1n', '\u0110\u00e3 \u1ea9n', 'Ch\u1edd ki\u1ec3m tra', 'Nh\u00e1p'].indexOf(row.status) >= 0).length, given: catId === 'promo' ? matching.filter((row) => row.status === '\u0110\u00e3 t\u1eb7ng').length : 0 }; }).concat(
st.added.filter((a) => a.cat === catId).map((a) => ({ id: a.id, title: '', price: '', stock: 0, given: 0, promo: catId === 'promo' ? 'Ch\u01b0a d\u00f9ng' : 'Ch\u01b0a c\u00f3' }))
).filter((s) => !st.delSubs[s.id]);
const titlesOf = (catId) => getSubs(catId).map((s) => ({ id: s.id, t: val(s.id, 't', s.title) || (catId === 'promo' ? '' : '(ch\u01b0a \u0111\u1eb7t ti\u00eau \u0111\u1ec1)') }));

const RULES0 = [];
const rulesAll = st.rulesData || RULES0;
const ruleExpired = (r) => !!(r.until && new Date(r.until + 'T23:59:59') < new Date());
const ruleNotYet = (r) => !!(r.from && new Date(r.from + 'T00:00:00') > new Date());
const activeRules = rulesAll.filter((r) => !r.paused && !ruleExpired(r) && !ruleNotYet(r));
const ruleText = (r) => 'Mua ' + r.buy + ' acc ' + r.buySub + ', tặng ' + r.give + ' acc ' + r.giveSub;
const promoOf = (catId, title) => {
if (catId === 'promo') { const n = rulesAll.filter((r) => r.giveSub === title).length; return n ? n + ' quy tắc' : 'Chưa dùng'; }
const rr = activeRules.find((r) => r.buySub === title);
return rr ? 'Mua ' + rr.buy + ' tặng ' + rr.give : 'Chưa có';
};

const cat = st.cat;
const isPromoCat = cat === 'promo';
const showSubs = cat !== 'all';
const subs = showSubs ? getSubs(cat).map((s) => ({
id: s.id,
title: val(s.id, 't', s.title),
price: val(s.id, 'p', s.price),
stock: String(s.stock),
hasPrice: !isPromoCat,
noPrice: isPromoCat,
promoText: promoOf(cat, val(s.id, 't', s.title)),
promoCol: /^(Mua|\d)/.test(promoOf(cat, val(s.id, 't', s.title))) ? ok : off,
del: () => askDelSub(s),
editTitle: setEdit(s.id, 't'),
editPrice: setEdit(s.id, 'p'),
pick: () => this.setState({ sub: st.sub === s.id ? 'all' : s.id, selIds: {} }),
bg: st.sub === s.id ? '#1F2538' : 'transparent',
pickLabel: st.sub === s.id ? 'Bỏ lọc' : 'Xem acc',
hasPic: (st.subPics[s.id] || []).length > 0, pic: (st.subPics[s.id] || [])[0] || '',
picLabel: (st.subPics[s.id] || []).length ? 'Thêm ảnh (' + (st.subPics[s.id] || []).length + ')' : 'Tải ảnh thư mục',
onPics: (e) => { const fl = e.target.files; if (!fl || !fl.length) return; this.compress(fl, (imgs, failed) => this.setState({ subPics: { ...this.state.subPics, [s.id]: (this.state.subPics[s.id] || []).concat(imgs) }, msg: 'Đã thêm ' + imgs.length + ' ảnh cho thư mục.' + (failed ? ' ' + failed + ' ảnh tải lên thất bại.' : '') })); },
clearPics: () => this.setState({ subPics: { ...this.state.subPics, [s.id]: [] }, msg: 'Đã gỡ ảnh thư mục.' })
})) : [];

const platFor = cat === 'reroll-ios' ? 'ios' : (cat === 'reroll-android' ? 'android' : 'all');
const rulePlat = (r) => (r.buySub.indexOf('iOS') >= 0 ? 'ios' : (r.buySub.indexOf('Android') >= 0 ? 'android' : 'all'));
const buyOptions = platFor === 'ios' ? titlesOf('reroll-ios') : (platFor === 'android' ? titlesOf('reroll-android') : titlesOf('reroll-ios').concat(titlesOf('reroll-android')));
const giftAll = titlesOf('promo');
const giftOptions = platFor === 'all' ? giftAll : giftAll.filter((o) => o.t.indexOf(platFor === 'ios' ? 'iOS' : 'Android') >= 0);
const giftFolders = giftAll.filter((o) => o.t && o.t.trim());
const effGiftSub = giftFolders.some((o) => o.id === st.giftSubSel) ? st.giftSubSel : (giftFolders.length === 1 ? giftFolders[0].id : '');

const all = [];
const lockedSt = ['Đã bán', 'Đã đặt giữ', 'Đã tặng'];
const merged = all.concat(st.listed).map((r) => ({ ...r, ...(st.ov[r.id] || {}) }));
const rows = merged
.filter((r) => !r.del && (cat === 'all' || r.cat === cat) && (st.sub === 'all' || r.sub === st.sub) && (st.inventoryFilter === 'all' || (isPromoCat ? (st.inventoryFilter === 'sold' ? r.status === '\u0110\u00e3 t\u1eb7ng' : r.status === 'Trong kho') : (st.inventoryFilter === 'sold' ? r.status === '\u0110\u00e3 b\u00e1n' : lockedSt.indexOf(r.status) < 0))))
.map((r) => ({ ...r, sub: r.info, salePct: num(r.cost) > num(r.price) && num(r.price) > 0 ? Math.round((num(r.cost) - num(r.price)) * 100 / num(r.cost)) : 0, catLabel: byId[r.cat].label, catCol: byId[r.cat].col, checked: !!st.selIds[r.id],
hasPic: (st.accPics[r.id] || []).length > 0, pic: (st.accPics[r.id] || [])[0] || '',
picLabel: 'Ảnh (' + (st.accPics[r.id] || []).length + ')',
onPics: (e) => { const fl = e.target.files; if (!fl || !fl.length) return; this.compress(fl, (imgs, failed) => this.setState({ accPics: { ...this.state.accPics, [r.id]: (this.state.accPics[r.id] || []).concat(imgs) }, msg: 'Đã thêm ' + imgs.length + ' ảnh cho acc ' + r.id + '.' + (failed ? ' ' + failed + ' ảnh tải lên thất bại.' : '') })); },
toggleSel: () => this.setState({ selIds: { ...this.state.selIds, [r.id]: !this.state.selIds[r.id] } }),
locked: lockedSt.indexOf(r.status) >= 0, editabilityLabel: lockedSt.indexOf(r.status) >= 0 ? 'Không thể chỉnh sửa' : 'Có thể chỉnh sửa', editabilityCol: lockedSt.indexOf(r.status) >= 0 ? '#FF8A1F' : '#43D9A0', lockOp: lockedSt.indexOf(r.status) >= 0 ? 0.4 : 1, cursor: lockedSt.indexOf(r.status) >= 0 ? 'not-allowed' : 'pointer',
tip: lockedSt.indexOf(r.status) >= 0 ? 'Acc đã bán, đặt giữ hoặc đã tặng không sửa hoặc xóa được' : '',
edit: () => openEdit(r.id), del: () => askDelAcc([r.id]) }));
const tabs = [{ id: 'all', label: 'T\u1ea5t c\u1ea3', count: '0' }].concat(cats).map((t) => ({
...t, count: String(merged.filter((r) => !r.del && (t.id === 'all' || r.cat === t.id)).length),
pick: () => this.setState({ cat: t.id, formCat: t.id === 'all' ? st.formCat : t.id, sub: 'all', subSel: '', selIds: {}, msg: '' }),
remove: (e) => askDelCategory(e, t),
line: t.id === cat ? on : 'transparent',
fg: t.id === cat ? '#EAEFFA' : off
}));
const current = cat === 'all' ? { count: String(merged.filter((r) => !r.del).length) } : byId[cat];

const fc = byId[st.formCat];
const folderCapable = ['RI', 'RA', 'KM'].indexOf(fc.code) >= 0 || !!fc.custom || getSubs(st.formCat).length > 0;
const subOptions = folderCapable ? titlesOf(st.formCat) : [];
const isBulk = st.mode === 'bulk';
const f = {
hint: fc.hint,
codeText: fc.code + '-tự động',
hasSub: subOptions.length > 0,
subLabel: fc.code === 'KM' ? 'Kho tặng thuộc mục' : 'Mục con',
freePlat: fc.plat === '',
char: fc.code === 'CI' || fc.code === 'CA',
team: fc.code === 'TM', custom: !!fc.custom,
showPrice: fc.code !== 'KM',
